import React from 'react';
import { Building2 } from 'lucide-react';

const MyApplications = () => {
  const apps = [
    { id: 1, company: "Global Soft", status: "مقبول", color: "emerald" },
    { id: 2, company: "IT Systems", status: "قيد المراجعة", color: "amber" }
  ];

  return (
    <div className="p-8 text-right" dir="rtl">
      <h1 className="text-2xl font-bold mb-8">تتبع طلباتي</h1>
      <div className="space-y-4">
        {apps.map(app => (
          <div key={app.id} className="bg-white p-6 rounded-2xl shadow-sm flex items-center justify-between border border-slate-100">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-slate-50 rounded-lg flex items-center justify-center"><Building2 className="text-slate-400"/></div>
              <h3 className="font-bold">{app.company}</h3>
            </div>
            <span className={`px-4 py-2 rounded-full bg-${app.color}-50 text-${app.color}-600 text-xs font-bold`}>
              {app.status}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};
export default MyApplications;
